import { GET_ALL_PRODUCTS, GET_ALL_PRODUCTS_SUCCESS, GET_ALL_PRODUCTS_FAIL } from '../actions/types';
const initData = {
  isLoading: false,
  products: [],
  isFail: false,
  isSuccess: false,
  totalPages:0
};
const productReducer = (state = initData, action) => {
  switch (action.type) {
    case GET_ALL_PRODUCTS:
      return {
        ...state,
        isLoading: true,
      };
    case GET_ALL_PRODUCTS_SUCCESS:
      return {
        ...state,
        products: [...state.products,...action.payload.shoes],
        totalPages:action.payload.totalPages,
        isLoading: false,
        isSuccess: true,
      };
    case GET_ALL_PRODUCTS_FAIL:
      return {
        ...state,
        isSuccess: false,
        isLoading: false,
        isFail: true,
      };
    default:
      return state;
  }
};

export default productReducer
